import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        double currentBalance = 5000.00;

        System.out.printf("Current Account Balance: Rs %.2f%n", currentBalance);
        System.out.print("Enter withdrawal amount: ");
        double withdrawalAmount = scanner.nextDouble();

        // Mutually exclusive binary decision:
        if (withdrawalAmount <= currentBalance && withdrawalAmount > 0) {
            currentBalance -= withdrawalAmount;
            System.out.printf("Transaction Successful! Please collect cash: Rs %.2f%n", withdrawalAmount);
            System.out.printf("Remaining Balance: Rs %.2f%n", currentBalance);
        } else {
            System.out.println("Transaction Declined: Insufficient balance or invalid amount.");
            System.out.printf("Available Balance remains: Rs %.2f%n", currentBalance);
        }

        System.out.println("Thank you for using National Bank ATM.");
        scanner.close();
    }
}

